package com.miniforce.service;
import com.miniforce.dto.*; import com.miniforce.dto.UserDtos.*; import com.miniforce.exception.NotFoundException; import com.miniforce.model.*; import com.miniforce.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class UserService {
 private static final Set<String> ALLOWED_AVATARS = Set.of("robot_01","cat_01","fox_01","panda_01","lion_01","frog_01","koala_01","tiger_01","monkey_01","unicorn_01","developer_01","gaming_01","rocket_01","lightning_01","terminal_01","controller_01","avatar_default");
 private final UserRepository users;private final SubmissionRepository submissions;private final ContestParticipantRepository participants; public UserService(UserRepository u,SubmissionRepository s,ContestParticipantRepository p){users=u;submissions=s;participants=p;}
 @Transactional public UserResponse update(User u,UpdateProfileRequest r){User entity=users.findById(u.getId()).orElseThrow(()->new NotFoundException("User not found"));if(r.fullName()!=null&&!r.fullName().isBlank())entity.setFullName(r.fullName().trim());if(r.bio()!=null)entity.setBio(r.bio().trim());entity=users.save(entity);return UserResponse.from(entity);}
 @Transactional public UserResponse updateAvatar(User u, UpdateAvatarRequest r){if(!ALLOWED_AVATARS.contains(r.avatarKey())){throw new IllegalArgumentException("Invalid avatar key");}User entity=users.findById(u.getId()).orElseThrow(()->new NotFoundException("User not found"));entity.setAvatarKey(r.avatarKey());entity=users.save(entity);return UserResponse.from(entity);}
 @Transactional(readOnly=true) public ProfileResponse profile(User u){User entity=users.findById(u.getId()).orElse(u);Map<String,Long> activity=new TreeMap<>(); for(Object[] row:submissions.activity(entity.getId(),Instant.now().minus(Duration.ofDays(365)))){String day=row[0].toString();activity.merge(day,((Number)row[1]).longValue(),Long::sum);}return new ProfileResponse(UserResponse.from(entity),participants.countByUserId(entity.getId()),submissions.findTop20ByUserIdOrderBySubmittedAtDesc(entity.getId()).stream().map(com.miniforce.dto.SubmissionDtos.SubmissionResponse::from).toList(),activity);}
 @Transactional(readOnly=true) public List<LeaderboardEntry> leaderboard(){List<User> all=users.findAll();all.sort(Comparator.comparingInt(User::getRating).reversed().thenComparing(Comparator.comparingInt(User::getSolvedCount).reversed()));List<LeaderboardEntry> result=new ArrayList<>();for(int i=0;i<all.size();i++)result.add(new LeaderboardEntry(i+1,UserResponse.from(all.get(i))));return result;}
 @Transactional(readOnly=true) public List<com.miniforce.dto.AdminDtos.AdminUserResponse> adminList(String search){return (search==null||search.isBlank()?users.findAll():users.findByUsernameContainingIgnoreCaseOrEmailContainingIgnoreCase(search,search)).stream().map(com.miniforce.dto.AdminDtos.AdminUserResponse::from).toList();}
 @Transactional public com.miniforce.dto.AdminDtos.AdminUserResponse adminRole(Long id,Role role){User u=users.findById(id).orElseThrow(()->new NotFoundException("User not found"));u.setRole(role);return com.miniforce.dto.AdminDtos.AdminUserResponse.from(u);}
}
